/* ============================================================
   COUNSELING MODULE STYLES
   ============================================================ */

/* Stat cards row */
.counsel-stat-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}
.counsel-stat-card {
  background: #fff;
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  box-shadow: var(--shadow-sm);
  border-left: 4px solid transparent;
  text-align: center;
}
.counsel-stat-card--waiting   { border-color: #F59E0B; }
.counsel-stat-card--active    { border-color: #3B82F6; }
.counsel-stat-card--done      { border-color: #10B981; }
.counsel-stat-card--total     { border-color: #8B5CF6; }
.counsel-stat-number {
  font-size: 2.2rem;
  font-weight: 800;
  line-height: 1.1;
  color: var(--gray-800);
}
.counsel-stat-label {
  font-size: .75rem;
  color: var(--gray-500);
  margin-top: 4px;
}

/* Tabs */
.counsel-tabs {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid var(--gray-200);
}
.counsel-tab {
  padding: 8px 16px;
  font-size: .85rem;
  font-weight: 600;
  color: var(--gray-500);
  border: none;
  background: none;
  cursor: pointer;
  border-bottom: 3px solid transparent;
  margin-bottom: -2px;
  display: flex;
  align-items: center;
  gap: 6px;
  transition: color .15s;
}
.counsel-tab:hover { color: var(--blue); }
.counsel-tab.active { color: var(--blue); border-bottom-color: var(--blue); }
.counsel-tab-badge {
  background: var(--gray-200);
  color: var(--gray-600);
  font-size: .7rem;
  padding: 1px 7px;
  border-radius: 99px;
  font-weight: 700;
}
.counsel-tab-badge--active { background: #DBEAFE; color: var(--blue); }
.counsel-tab-badge--done   { background: #D1FAE5; color: var(--green-dark); }

/* Counseling Panel (slide-in from right) */
.counsel-panel-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.35);
  z-index: 200;
}
.counsel-panel {
  position: fixed;
  top: 0;
  right: 0;
  width: min(600px, 100vw);
  height: 100vh;
  background: #fff;
  z-index: 201;
  display: flex;
  flex-direction: column;
  box-shadow: -4px 0 32px rgba(0,0,0,.18);
  animation: slideInRight .2s ease;
}
@keyframes slideInRight {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
.counsel-panel.hidden,
.counsel-panel-backdrop.hidden { display: none !important; }

.counsel-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 20px;
  background: linear-gradient(135deg, #059669, #047857);
  color: #fff;
  flex-shrink: 0;
}
.counsel-panel-title { font-size: 1.1rem; font-weight: 700; }
.counsel-panel-subtitle { font-size: .78rem; opacity: .85; margin-top: 2px; }

.counsel-patient-summary {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  padding: 10px 20px;
  background: var(--gray-50);
  border-bottom: 1px solid var(--gray-200);
  flex-shrink: 0;
}
.counsel-summary-item {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.counsel-summary-label {
  font-size: .68rem;
  text-transform: uppercase;
  letter-spacing: .05em;
  color: var(--gray-500);
}

.counsel-panel-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
}

/* Procedure search */
.counsel-proc-search-wrap {
  margin-bottom: 10px;
}
.counsel-proc-search-wrap input {
  width: 100%;
  padding: 7px 12px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius);
  font-size: .85rem;
}
.counsel-proc-search-wrap input:focus {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 3px rgba(16,185,129,.15);
}

/* Procedure checkbox list */
.counsel-proc-list {
  max-height: 260px;
  overflow-y: auto;
  border: 1px solid var(--gray-200);
  border-radius: var(--radius);
  background: #fff;
}
.proc-category-group { }
.proc-category-label {
  background: var(--gray-100);
  padding: 4px 10px;
  font-size: .7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: .06em;
  color: var(--gray-500);
  position: sticky;
  top: 0;
}
.proc-checkbox-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  cursor: pointer;
  font-size: .82rem;
  border-bottom: 1px solid var(--gray-100);
  transition: background .1s;
}
.proc-checkbox-row:hover { background: #F0FDF4; }
.proc-checkbox-row.checked { background: #DCFCE7; }
.proc-checkbox { width: 15px; height: 15px; accent-color: var(--green); flex-shrink: 0; }
.proc-name { flex: 1; }

/* Selected procedures */
.selected-proc-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 0;
  border-bottom: 1px solid var(--gray-100);
  font-size: .82rem;
}
.selected-proc-name { flex: 1; color: var(--gray-700); }
.proc-price-input {
  width: 90px;
  padding: 4px 8px;
  border: 1px solid var(--gray-300);
  border-radius: var(--radius);
  font-size: .82rem;
  text-align: right;
}
.proc-price-input:focus {
  outline: none;
  border-color: var(--green);
  box-shadow: 0 0 0 2px rgba(16,185,129,.15);
}

/* Total row */
.counsel-total-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-top: 10px;
  padding: 8px 12px;
  background: #ECFDF5;
  border: 1px solid #A7F3D0;
  border-radius: var(--radius);
  font-size: .88rem;
}
.counsel-total-row strong { font-size: 1rem; color: var(--green-dark); }

/* Panel Footer */
.counsel-panel-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 20px;
  border-top: 1px solid var(--gray-200);
  background: var(--gray-50);
  flex-shrink: 0;
}

/* Success button */
.btn--success {
  background: var(--green);
  color: #fff;
  font-weight: 600;
  padding: 8px 18px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: background .15s;
}
.btn--success:hover { background: var(--green-dark); }
.btn--success:disabled { background: var(--gray-300); cursor: not-allowed; }

/* Warning button */
.btn--warning {
  background: #F59E0B;
  color: #fff;
  font-weight: 600;
  padding: 6px 14px;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  font-size: .82rem;
}
.btn--warning:hover { background: #D97706; }

/* Counseling status badges on reception */
.counsel-badge {
  font-size: .68rem;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 99px;
  display: inline-block;
  margin-top: 2px;
}
.counsel-badge--waiting      { background: #FEF3C7; color: #92400E; }
.counsel-badge--in_counseling{ background: #DBEAFE; color: #1D4ED8; }
.counsel-badge--done         { background: #D1FAE5; color: #065F46; }

/* Print stylesheet for token printing */
@media print {
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  body { margin: 0; padding: 0; background: white; }
  .no-print, header, nav, .page-header, .top-tabs, .toolbar, .stat-cards-wrapper, .booking-table-wrapper { display: none !important; }
}

