function openPrintSlip(sessionId, bookingId) {
  const url = `./print-slip.html?session_id=${encodeURIComponent(sessionId)}&booking_id=${encodeURIComponent(bookingId)}`;
  window.open(url, '_blank', 'width=500,height=700');
